import{_ as s,C as i,o as n,c as r,j as t,a as h,E as o,a2 as l}from"./chunks/framework.sc8Z_ZE3.js";const f=JSON.parse('{"title":"How a pull request goes in","description":"","frontmatter":{},"headers":[],"relativePath":"contribute/pull-requests.md","filePath":"contribute/pull-requests.md"}'),d={name:"contribute/pull-requests.md"};function c(p,e,g,u,m,k){const a=i("Badge");return n(),r("div",null,[e[0]||(e[0]=t("h1",{id:"how-a-pull-request-goes-in",tabindex:"-1"},[h("How a pull request goes in "),t("a",{class:"header-anchor",href:"#how-a-pull-request-goes-in","aria-label":'Permalink to "How a pull request goes in"'},"​")],-1)),o(a,{type:"built",text:"Built"}),e[1]||(e[1]=l(' Every change goes through the same steps, whether a person or an agent wrote it.<h2 id="_1-start-from-an-issue" tabindex="-1">1. Start from an issue <a class="header-anchor" href="#_1-start-from-an-issue" aria-label="Permalink to &quot;1. Start from an issue&quot;">​</a></h2><p>Anything bigger than a small fix starts from an issue that says what and why. Larger work is split into slices that can each be verified on their own; if a slice grows beyond its boundary, split the rest into a new one.</p><h2 id="_2-branch-and-change" tabindex="-1">2. Branch and change <a class="header-anchor" href="#_2-branch-and-change" aria-label="Permalink to &quot;2. Branch and change&quot;">​</a></h2><p>Branch from the integration branch. One change per pull request, with its tests. Keep it small and focused, and update the nearest documentation when behaviour or workflow changes.</p><h2 id="_3-run-the-merge-gate" tabindex="-1">3. Run the merge gate <a class="header-anchor" href="#_3-run-the-merge-gate" aria-label="Permalink to &quot;3. Run the merge gate&quot;">​</a></h2><p>The merge gate runs locally and its summary goes into the pull request description:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/full-regression.sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pr</span></span></code></pre></div><p>Every step always runs, and the gate is green only if every step exits 0:</p><table tabindex="0"><thead><tr><th>Step</th><th>What it checks</th></tr></thead><tbody><tr><td><code>lock</code></td><td>the dependency lock file is current</td></tr><tr><td><code>ruff</code></td><td>the backend linter, whole tree</td></tr><tr><td><code>ruff-cli</code></td><td>the launcher&#39;s changed Python files</td></tr><tr><td><code>secrets</code></td><td>no secret in the branch&#39;s own commits (gitleaks)</td></tr><tr><td><code>backend</code></td><td>the backend tests; in <code>--mode pr</code> the tests a coverage map selects for the changed files, or all of them when a change cannot be placed. A selection that runs no test is red.</td></tr><tr><td><code>clients</code></td><td>the launcher&#39;s tests, when the branch changes it</td></tr></tbody></table><p>For a change in <code>frontend/chat</code>, also run there:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noEmit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eslint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The full mode (the default) runs everything; it runs nightly and before a release.</p><p>The pull request says what changed and how it was tested; its template asks for both.</p><h2 id="_4-review" tabindex="-1">4. Review <a class="header-anchor" href="#_4-review" aria-label="Permalink to &quot;4. Review&quot;">​</a></h2><p>The <a href="/docs/review-bot/">review bot</a> reviews the pull request like any other: a summary, inline findings with severity, file and line, and the commit status <code>octryx/review</code>. A maintainer reviews too. Answer findings in the thread; the bot understands <a href="/docs/review-bot/commands">commands</a>.</p><h2 id="_5-merge" tabindex="-1">5. Merge <a class="header-anchor" href="#_5-merge" aria-label="Permalink to &quot;5. Merge&quot;">​</a></h2><p>Only a fully green pull request is merged: no red test, no open blocking finding. Octryx AI itself never merges; a maintainer does.</p><h2 id="commit-messages" tabindex="-1">Commit messages <a class="header-anchor" href="#commit-messages" aria-label="Permalink to &quot;Commit messages&quot;">​</a></h2><p>Say what changed and why, in English, in the imperative. One logical change per commit.</p>',20))])}const y=s(d,[["render",c]]);export{f as __pageData,y as default};
